INSERT INTO `plan_templates` (`id`, `type`, `template_for`, `title`, `data`, `created_at`, `updated_at`, `deleted_at`) VALUES
                                                                                                                           (1, 'plan_extension', NULL, 'म्याद थप गरिएको बारे', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n...............................</span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:22px\"><strong>विषय:- म्याद थप गरिएको बारे।</strong></span></h4>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; प्रस्तुत विषयमा त्यस समिति र यस कार्यालय बिच मिति ........................ गते भएको सम्झौता अनुसार ............................... योजनाको मिति ........................... गते सम्म सम्पुर्ण कार्य सम्पन्न गर्नुपर्नेमा कार्य सम्पन्न नभएकाले उक्त योजनाको मिति ....................... गते सम्म म्याद थप गरिएको व्यहोरा जानकारी गराईन्छ ।</span></p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem\"><span style=\"font-size:18px\"><strong>....................................</strong></span><br />\r\n<span style=\"font-size:16px\">योजना शाखा प्रमुख<br />\r\nबोधार्थ :-</span><span style=\"font-size:18px\"><strong> </strong></span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:18px\"><strong>...................................</strong></span><br />\r\n<span style=\"font-size:16px\">प्रमुख प्रशासकिय अधिकृत</span></div>\r\n</div>', '2023-01-22 08:15:30', '2023-01-22 08:19:49', NULL),
                                                                                                                           (2, 'comment_order', NULL, 'योजना सम्झौता सम्बन्धमा', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">टिप्पणी संख्या: ................................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................<br />\r\nपाना नं.: ..............................</span></p>\r\n</div>\r\n</div>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय:- योजना सम्झौता सम्बन्धमा ।<br />\r\n(टिप्पणी र आदेश)</strong></span></h4>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\">श्रीमान,</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; प्रस्तुत विषयमा चालु आ.ब. .................. का लागी यस ..................... को मिति ..................... गतेको ........................ नगर सभाबाट, स्विकृत .............................. योजना निर्माणका लागि वडा नम्बर .......................... मा ......................... अन्य संचालन हुने योजना बाट रु. ............................... विनियोजित भएकोमा मिति ....................... गते उपभोक्ता समिति गठन भई मिति गते उपभोक्ता समितिले योजना सम्झौता गर्ने निर्णय गरेको मिति .......................... गते समबन्धित वडा कार्यालय बाट योजना सम्झौता गरिदिने भन्ने बारेको यस कार्यालयलाई सिफारिस गरेको र उपभोक्ता समितिले मिति ........................ गते योजना सम्झौता गरिदिने भन्ने बारेको निबेदन यस कार्यालयमा दिइ स्विकृत भई प्राविधिक लागत अनुमान समेत तयार भई स्विकृत समेत भएकोले सम्झौताका लागी पेश गर्दछु।</span></p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem\"><span style=\"font-size:16px\"><u><strong>पेश गर्ने</strong></u></span><br />\r\n<span style=\"font-size:14px\">नाम :- .......................<br />\r\nपद :- ........................<br />\r\nमिति :- .......................<br />\r\nदस्तखत :- .................</span><span style=\"font-size:18px\"><strong> </strong></span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem\"><u><span style=\"font-size:16px\"><strong>सिफारिश गर्ने</strong></span></u><br />\r\n<span style=\"font-size:14px\">नाम :- .......................<br />\r\nपद :- .........................<br />\r\nमिति :- .......................<br />\r\nदस्तखत :- ................</span></div>\r\n</div>', '2023-01-22 08:45:45', '2023-01-29 04:58:32', NULL),
                                                                                                                           (3, 'bank_account_operation_recommendation', NULL, 'सिफारिस गरि पठाईएको बारे', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/Tekchan/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n...............................</span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:22px\"><strong>विषय:- सिफारिस गरि पठाईएको बारे ।</strong></span></h4>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14px\">प्रस्तुत बिषय सम्बन्धमा यस ...................... र&nbsp;</span>[@consumerCommittee.name]<span style=\"font-size:14px\"> समिति बिच वडा नं.&nbsp;</span>[@ward_no]<span style=\"font-size:14px\"> ,&nbsp;</span>[@project_name]<span style=\"font-size:14px\"> योजना कार्यान्वयन गर्ने सम्झौता भए बमोजिम उपभोक्ता समितिको नाममा खाता खोल्नु पर्ने भएको हुँदा ..................... नामको तहाँ बैंकमा नयाँ खाता खोली अध्यक्ष श्री&nbsp;</span>[@consumerCommittee.chairman]<span style=\"font-size:14px\"> , कोषाध्यक्ष श्री .................... र सचिव श्री ................... को संयुत्त दस्तखतबाट खाता सन्चालन गरिदिनु हुन सिफारिस साथ अनुरोध छ ।</span></p>\r\n\r\n<div class=\"text-end\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-size:14px\">....................................<br />\r\nप्रमुख प्रशासकिय अधिकृत</span></p>\r\n</div>', '2023-01-22 08:58:31', '2023-01-29 06:23:34', NULL),
                                                                                                                           (4, 'mandate', 'consumer_committee', 'कार्यादेश दिईएको बारे', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति : &nbsp;</span>[@date]</p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<h4 style=\"text-align:center\">&nbsp;</h4>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:22px\"><strong>विषय:- कार्यादेश दिईएको बारे ।</strong></span></h4>\r\n\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n...............................</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>प्रस्तुत विषयमा त्यस समिति र यस कार्यालय बिच मिति ................... गते भएको सम्झौता अनुसार ................... योजनाको सम्झौतामा तोकिएको शर्त र प्रस्ताव बमोजिम उक्त कार्यको कार्यान्वयन यथासिघ्र शुरु गरी मिति ...................... गते सम्म गुणस्तरयुक्त तरिकाले कार्य सम्पन्न गर्नु हुन यो कार्यादेश दिइएको छ ।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2 style=\"text-align:center\"><strong>तपशिल:</strong></h2>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"height:434px; width:1035px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>सि.नं.</strong></td>\r\n			<td><strong>बिषय/विवरण</strong></td>\r\n			<td><strong>रकम</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td>१</td>\r\n			<td>आर्थिक बर्ष : [@fiscalYear]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>२</td>\r\n			<td>अयोजनाको नाम : [@project_name]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>३</td>\r\n			<td>ठेगाना : [@project_venue]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>४</td>\r\n			<td>योजना स्वीकृत मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>५</td>\r\n			<td>बजेट शिर्षक नं : [@registration_no]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>६</td>\r\n			<td>कार्यक्रमको नाम :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>७</td>\r\n			<td>उपभोग्ता समितिको नाम : [@consumerCommittee.name]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>८</td>\r\n			<td>उपभोग्ता समितिको बैंक खाता नं:</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>९</td>\r\n			<td>उपभोग्ता समितिसंग सम्झौता मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१०</td>\r\n			<td>उपभोग्ता समितिको निर्णय मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>११</td>\r\n			<td>स्वीकृत रकम :</td>\r\n			<td>रु . [@allocated_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१२</td>\r\n			<td>लागत अनुमान:</td>\r\n			<td>रु . [@total_cost_estimate_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td><strong>लागत व्यहोर्ने श्रोतहरु : </strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१३</td>\r\n			<td>कार्यालयबाट रु.[@total_cost_estimate_amount]</td>\r\n			<td>रु . [@total_amount_for_contingency]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१४</td>\r\n			<td>उपभोग्ता समितिबाट रु.</td>\r\n			<td>रु . [@committee_share_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१५</td>\r\n			<td>अन्यबाट रु.</td>\r\n			<td>रु . [@share_amount]</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>...................................<br />\r\nप्रमुख प्रशासकिय अधिकृत</p>', '2023-01-22 09:11:49', '2023-01-29 08:54:12', NULL),
                                                                                                                           (5, 'schedule_3', NULL, 'सार्वजनिक परीक्षण फाराम पेश गरेको कार्यालय', '<p style=\"text-align:center\"><strong><span style=\"font-size:20px\">अनुसूची ३</span></strong></p>\r\n\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:5rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:16px\">सार्वजनिक परीक्षण फाराम पेश गरेको कार्यालय</span></p>\r\n\r\n<p style=\"text-align:center\"><br />\r\n<span style=\"font-size:14px\">...................................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">१. आयोजनाको नाम : </span>[@project_name]</p>\r\n\r\n<div class=\"d-flex flex-container\" style=\"display:flex; margin-bottom:1em; margin-left:1em; margin-right:1em; margin-top:1em\">\r\n<div class=\"auto item\"><span style=\"font-size:14px\">(क) स्थल: </span>[@project_venue] <span style=\"font-size:14px\">ख) लागत अनुमान </span>: [@total_cost_estimate_amount]<span style=\"font-size:14px\"> ग) आयोजना शुरू हुने मित</span> : [@project_start_date] <span style=\"font-size:14px\">घ) आयोजना सम्पन्न हुने मिति : </span>[@project_completion_date]</div>\r