/td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:14px\">उपर्युक्तानुसारको आम्दानी तथा खर्च विवरण यथार्थ हो । यसमा सबै आम्दानी तथा खर्चहरु समावेश गरिएको छ । साथै उपभोक्ताहरुको प्रत्यक्ष सहभागितामा आयोजना कार्यान्वयन गरिएको छ । यसको एक प्रति वडा कार्यालयमा समेत पेश गरिएको छ ।</span></p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nसचिव</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">...................................<br />\r\nअध्यक्ष</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">...................................<br />\r\nकोषाध्यक्ष</span></div>\r\n</div>\r\n\r\n<p>&nbsp;</p>', '2023-01-22 11:31:59', '2023-01-22 11:31:59', NULL),
                                                                                                                           (7, 'schedule_5', NULL, 'आयोजना सूचना पाटीको नमूना', '<p style=\"text-align:center\"><strong><span style=\"font-size:20px\">अनुसूची ५</span></strong></p>\r\n\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:5rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><strong><span style=\"font-size:16px\">आयोजना सूचना पाटीको नमूना</span></strong></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14px\">१. आयोजनाको नाम : ............................<br />\r\n२. आयोजना संचालन गर्ने कार्यालय/कार्यक्रमको नाम : ............................<br />\r\n३. उपभोक्ता समितिको अध्यक्षको नाम : ............................<br />\r\n४. उपभोक्ता समितिको अध्यक्षको सम्पर्क नं : ............................<br />\r\n५. आयोजनाको कुल लागत रकम रु : ............................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; ५.१. आयोजनामा कार्यालयबाट व्यहोर्ने लागत रु : ............................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; ५.२. जनसहभागिताबाट व्यहोर्ने लागत रकम रु : ............................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; ५.३. आयोजनामा लगानी गर्ने अन