                                                                                                                           (8, 'schedule_6', NULL, 'उपभोक्ता समितिको भौतिक तथा वित्तीय प्रगति प्रतिवेदन', '<p style=\"text-align:center\"><strong><span style=\"font-size:20px\">अनुसूची ६</span></strong></p>\r\n\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:5rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:16px\">उपभोक्ता समितिको भौतिक तथा वित्तीय प्रगति प्रतिवेदन<br />\r\nविवरण पेश गरेको कार्यालय<br />\r\n.....................................</span></p>\r\n\r\n<p><span style=\"font-size:18px\">१. आयोजनाको विवरण</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp; आयोजनाको नाम: ........&nbsp; वडा नं:...........&nbsp; टोल&divide;बस्तीः..........&nbsp; उपभोक्ता समितिका अध्यक्षः...............&nbsp; सचिवः...................</span></p>\r\n\r\n<p><span style=\"font-size:18px\">२. आयोजनाको लागतः प्राप्त अनुदान रकम रू : ............................ चन्दा रकम रू : ......................</span></p>\r\n\r\n<div class=\"d-flex flex-container\" style=\"display:flex; margin-bottom:1em; margin-left:1em; margin-right:1em; margin-top:1em\">\r\n<div class=\"auto item\"><span style=\"font-size:18px\">जनसहभागिता रकम रू : ..........................&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; जम्मा रकम रू. :.................................. &nbsp; </span></div>\r\n</div>\r\n\r\n<p><span style=\"font-size:18px\">३. हालसम्मको खर्च रू :.........................</span></p>\r\n\r\n<p><span style=\"font-size:18px\">क. कार्यालयबाट प्राप्त रकम रू :......................</span></p>\r\n\r\n<p><span style=\"font-size:18px\">१. निर्माण सामग्रीमा (सिमेन्ट, छड, काठ, ढुंगा वा फुवा, गिट्टी, उपकरण आदि) रू :...........................</span></p>\r\n\r\n<p><span style=\"font-size:18px\">२. ज्याला :.................. दक्ष रू :.................... अदक्ष रू :................. जम्मा रू :..........................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">३. मसलन्द सामान (कपि, कलम, मसी, कागज आदि) रू :.................................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">४. दैनिक भ्रमण भत्ता (सम्झौतामा स्वीकृत भए) रू :..........................................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">५. प्राविधिक निरीक्षण बापत खर्च (सम्झौतामा स्वीकृत भए) रू :.................................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">६. अन्य</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">जनसहभागिताबाट व्यहोरिएको खर्च रू :...............................................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\"><span style=\"font-size:18px\">श्रमको मूल्य बराबर रकम र :..............................................................</span></p>\r\n\r\n<p style=\"margin-left:0; margin-right:0; text-align:justify\">