                                                                                                                           (10, 'plan_supervision_monitoring_report', NULL, 'योजना सुपरीवेक्षण तथा अनुगमन प्रतिवेदन', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: .................</span><span style=\"font-size:14px\">.................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<h4 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय:- योजना सुपरीवेक्षण तथा अनुगमन प्रतिवेदन ।</strong></span></h4>\r\n\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n..................................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">१. आयोजना/योजनाको विस्तृत विवरण :<br />\r\n&nbsp;&nbsp;&nbsp; १.१) आयोजना/योजना/कार्यक्रमको नाम :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.२) ठेगाना :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.३) आयोजना/योजना/कार्यक्रम सञ्चालन समिति/निर्माण व्यवसायीको नाम :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.४) आयोजना/योजनाको जम्मा रकम रु. :...........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; क) सम्बन्धित स्थानिय तहको रकम रु. :...........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ख) जनश्रमदान रकम रु. :...........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ग) अन्य निकाय, कार्यालय वा विकास साझेदारको नाम र सहयोग रकम रु. :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.५) आयोजना/योजना सम्झौता भएको मिति :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.६) आयोजना/योजना सम्पन्न गर्नुपर्ने मिति :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.७) आयोजना/योजना सम्पन्न भएको मिति :...........................<br />\r\n&nbsp;&nbsp;&nbsp; १.८) आयोजना/योजनाको सुपरिवेक्षण तथा अनुगमन गरिएको मितिः :...........................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">२. निर्माण प्रक्रिया :<br />\r\n(क) उपभोक्ता समिति :........... (ख) विषयगत कार्यालय :............ (ग) सामुदायिक संस्था :............. (घ) गैरसरकारी संस्था :........... (ङ) सार्वजनिक निजी साझेदारी :................. (च) ठेक्कापट्टा :..................&nbsp; (छ) अमानत :.........................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">३. आयोजना/योजनाको अनुगमन गर्नुपर्ने पक्षहरु :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; ३.१) आयोजना/योजनामा संलग्न साझेदारहरूले लागत सहभागिता वा जनसहभागिता <input name=\"approve\" required=\"required\" type=\"checkbox\" /> जनाएको <input name=\"non\" required=\"required\" type=\"checkbox\" /> नजनाएको (जनाएको भए प्रतिशतमा राख्ने)<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; जम्मा लागत सहभागिता (प्रतिशतमा %) :....................................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; जम्मा जनश्रमदान/सहभागिता (प्रतिशतमा %) :.............................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp; ३.२) तोकिएको उद्देश्यमा लगानी भए नभएको :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ३.२.१ लक्षित वर्ग कार्यक्रम :&nbsp;&nbsp; <input name=\"a\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"b\" required=\"required\" type=\"checkbox\" /> नभएको&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ३.२.२ पुर्वाधार विकास कार्यक्रम :&nbsp; <input name=\"c\" required=\"required\" type=\"checkbox\" />भएको&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"d\" required=\"required\" type=\"checkbox\" /> नभएको<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; ३.२.३ आयआर्जन कार्यक्रम :&nbsp; &nbsp;<input name=\"e\" required=\"required\" type=\"checkbox\" /> भएको &nbsp; &nbsp; &nbsp;<input name=\"f\" required=\"required\" type=\"checkbox\" /> नभएको&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; ३.२.४ सिपमुलक कार्यक्रम :&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"g\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"h\" required=\"required\" type=\"checkbox\" /> नभएको<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; ३.२.५ अन्य कार्यक्रमः :&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"i\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"j\" required=\"required\" type=\"checkbox\" />नभएको</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp; ३.३) आयोजना/योजना वा कार्यक्रममा भएको खर्चको विवरण तथा सोको बिल, भरपाई, स्रेस्ता रीतपूर्वक <input name=\"store\" required=\"required\" type=\"checkbox\" />राखेको&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"not\" required=\"required\" type=\"checkbox\" />नराखेको</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp; ३.४) आयोजना/योजना वा कार्यक्रमको स्वीकृत सम्झौता रकम बराबर काम <input name=\"yes\" required=\"required\" type=\"checkbox\" />भएको&nbsp;&nbsp;&nbsp; <input name=\"no\" required=\"required\" type=\"checkbox\" />नभएको (नभएको भए कारणहरु)<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; १ ........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २ ........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; ३ ........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ४ ........................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ५ ........................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">४. भौतिक पक्ष :<br />\r\n&nbsp;&nbsp;&nbsp; १) सुपरीवेक्षण :&nbsp;&nbsp;&nbsp; <input name=\"k\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"l\" required=\"required\" type=\"checkbox\" /> नभएको<br />\r\n&nbsp;&nbsp;&nbsp; २) लक्षित समुहकोे सहभागिता :&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"m\" required=\"required\" type=\"checkbox\" />भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"n\" required=\"required\" type=\"checkbox\" /> नभएको</span></p>\r\n\r\n<div style=\"page-break-after:always\"><span style=\"display:none\">&nbsp;</span></div>\r\n\r\n<p><br />\r\n<span style=\"font-size:14px\">३) योजनाको भौतिक कार्य प्रगतिको अवस्था :</span></p>\r\n\r\n<table cellspacing=\"0\" class=\"MsoTableGrid\" style=\"border-collapse:collapse; border:medium none; height:376px; width:897px\">\r\n	<tbody>\r\n		<tr>\r\n			<td rowspan=\"2\" style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; height:36px; vertical-align:top; width:60px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"font-family:&quot;Calibri&quot;,sans-serif\"><span style=\"font-family:Kalimati\">क्र.सं</span></span></span></p>\r\n			</td>\r\n			<td rowspan=\"2\" style=\"bord