-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:78px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><input name=\"is_not_complete_4\" required=\"required\" type=\"checkbox\" /></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:113px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><input name=\"Satisfactory_4\" required=\"required\" type=\"checkbox\" /></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:60px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\">५.</span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:73px\">\r\n			<p style=\"text-align:center\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:103px\">\r\n			<p style=\"text-align:center\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:106px\">\r\n			<p style=\"text-align:center\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:47px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><input name=\"is_complete_5\" required=\"required\" type=\"checkbox\" /></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:78px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><input name=\"is_not_complete_5\" required=\"required\" type=\"checkbox\" /></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:15px; vertical-align:top; width:113px\">\r\n			<p style=\"text-align:center\"><span style=\"font-size:14px\"><input name=\"Satisfactory_5\" required=\"required\" type=\"checkbox\" /></span></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:14px\">५) योजनावाट लाभान्वित संख्या :</span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">विवरण</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">दलित</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">जनजाति</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">महिला</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">अन्य</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">जम्मा</span></span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">लाभान्वित घरधुरी</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">लाभान्वित जनसंख्या</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:14px\">५. उपभोक्ता समितिको पक्ष :<br />\r\n&nbsp;&nbsp;&nbsp; १) उपभोक्ता समितिको गठन/पुनर्गठन चरणको सहभागिता :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; क) गठन/पुनर्गठन मिति :........................ (ख) उपस्थिति संख्या(जना) :..................<br />\r\n&nbsp;&nbsp;&nbsp; २) उपभोक्ता समितिको सदस्य संख्या :<br />\r\n&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; क) महिला :........... ख) पुरुष :........... ग) दलित :............ घ) आदिवासी जनजाति :.......... ङ) अन्य :.........</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ३) उपभोक्ता समितिको निर्णय पुस्तिका चुस्त र दुरुस्त अवस्थामा <input name=\"o\" required=\"required\" type=\"checkbox\" /> भएको&nbsp; <input name=\"p\" required=\"required\" type=\"checkbox\" /> नभएको (नभएको भए कारणहरु)</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ४) उपभोक्ता समितिको वैठक बस्ने <input name=\"q\" required=\"required\" type=\"checkbox\" /> गरेको&nbsp;&nbsp; <input name=\"r\" required=\"required\" type=\"checkbox\" /> नगरेको<br />\r\n&nbsp; &nbsp; &nbsp;&nbsp; वस्ने गरेको भए &nbsp;<input name=\"s\" required=\"required\" type=\"checkbox\" /> (क) पाक्षिक &nbsp;&nbsp;<input name=\"t\" required=\"required\" type=\"checkbox\" /> (ख) मासिक &nbsp; (ग) ............................&nbsp; पटक</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ५) उपभोक्ता समितिको अध्यक्ष, सचिव र कोषाध्यक्षको नाम र सम्पर्क फोन नमवर :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (अध्यक्ष) नाम :......................... &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; फोन :..............................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (सचिव) नाम :.......................... &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; फोन :..............................<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (कोषाध्यक्ष) नाम :.....................&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; फोन :...............................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ६) सार्वजनिक लेखा परीक्षण, सुनुवाई जस्ता पारदर्शिता सम्बन्धी काम&nbsp;&nbsp; <input name=\"u\" required=\"required\" type=\"checkbox\" /> गरेको&nbsp;&nbsp;&nbsp; <input name=\"v\" required=\"required\" type=\"checkbox\" /> नगरेको<br />\r\n&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; गरेको भए&nbsp; <input name=\"w\" required=\"required\" type=\"checkbox\" /> (क) पाक्षिक&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"x\" required=\"required\" type=\"checkbox\" />(ख) मासिक&nbsp;&nbsp; (ग) ............................. पटक</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ७) आयोजना/योजना वा कार्यक्रमको कार्यन्वयन स्थलमा सूचना पाटी&nbsp;&nbsp; <input name=\"z\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp; <input name=\"is_not\" required=\"required\" type=\"checkbox\" /> नभएको</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ८) आयोजना&divide;योजना वा कार्यक्रमसँग सम्बन्धित फोटाहरु पेश&nbsp;&nbsp; <input name=\"is_1\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp; <input name=\"is_not_1\" required=\"required\" type=\"checkbox\" /> नभएको</span></p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp; ९) आयोजना/योजनाको दिगो व्यवस्थापन सम्बन्धमा भएको प्रयास<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; क) संचालनमा आएका समस्याहरुको समाधान :&nbsp;&nbsp; <input name=\"is_2\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"is_not_2\" required=\"required\" type=\"checkbox\" />नभएको<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ख) मर्मत सम्भार कोष स्थापना :&nbsp;&nbsp; <input name=\"is_3\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"is_not_3\" required=\"required\" type=\"checkbox\" /> नभएको<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ग) व्यवस्थापन समिति गठन :&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"is_4\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; <input name=\"is_not_4\" required=\"required\" type=\"checkbox\" /> नभएको<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; घ) हेरालु/चौकिदारको व्यवस्था : &nbsp;&nbsp;<input name=\"is_5\" required=\"required\" type=\"checkbox\" /> भएको&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <input name=\"is_not_5\" required=\"required\" type=\"checkbox\" /> नभएको</span></p>\r\n\r\n<p><span style=\"font-size:14px\">६. आयोजना/योजनाबाट वातावरणीय क्षेत्रमा पार्ने कुनै असर भए उल्लेख गर्ने :<br />\r\n.........................................................................................................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">७. आयोजना/योजना/कार्यक्रम संचालनमा देखिएका समस्या तथा चुनौर्तीे :<br />\r\n.........................................................................................................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">८. आयोजना/योजना/कार्यक्रमप्रति आम उपभोक्ताको धारणा :<br />\r\n.........................................................................................................</span></p>\r\n\r\n<div style=\"page-break-after:always\"><span style=\"display:none\">&nbsp;</span></div>\r\n\r\n<p><span style=\"font-size:14px\">९. आयोजना/योजना र वजेटबाट प्राप्त उपलब्धी बारे लेख्ने :<br />\r\n.........................................................................................................</span></p>\r\n\r\n<p><span style=\"font-size:14px\">१०. अनुगमन गर्ने पदाधिकारीहरू</span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">क्र.सं</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">पुरा नाम/थर</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">पद</span></span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">दस्तखत</span></span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">१</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">नगर प्रमुख</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">२</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">नगर उपप्रमुख</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">३</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">वडा अध्यक्ष</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">४</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">कार्यपालिका सदस्य</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">५</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">प्र.प्र. अधिकृत</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">६</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">योजना शाखा प्रमुख</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">७</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">इन्जिनियर</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">८</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\"><span style=\"background-color:#fafafa; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif\">इन्जिनियर</span></span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">९</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">१०</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:14px\">११. अनुुगमन तथा सुपरिवेक्षण समितिको आयोजना/योजना/कार्यक्रमको फरफारक गर्न मनासिव भए वा नभएको छोटो राय/टिप्पणी :<br />\r\nअनुगमन समितिद्वारा यस योजनाको स्थलगत निरीक्षण तथा अनुगमन गर्दा प्राविधिक लागत इस्टिमेट बमोजिमको कार्य सम्पन्न गुणस्तरीय/सन्तोषजनक ....................... उपभोक्ता समितिको तर्फबाट जनश्रमदान उत्कृष्ठ ............................. तथा नियमानुसार सार्वजनिक परिक्षण समेत ........................... पाइएको ले सो योजना फरफारक गर्न मनासिव देखिन्छ/देखिदैन ।</span></p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem\"><span style=\"font-size:14px\"><u><strong>सिफारिश गर्ने</strong></u><br />\r\nनाम :- .......................<br />\r\nपद :- ........................<br />\r\nमिति :- .......................<br />\r\nदस्तखत :- .................<strong> </strong></span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem\"><span style=\"font-size:14px\"><u><strong>प्रमणित गर्ने</strong></u><br />\r\nनाम :- .......................<br />\r\nपद :- .........................<br />\r\nमिति :- .......................<br />\r\nदस्तखत :- ................</span></div>\r\n</div>\r\n\r\n<p>&nbsp;</p>', '2023-01-23 09:46:01', '2023-01-23 09:46:01', NULL);
INSERT INTO `plan_templates` (`id`, `type`, `template_for`, `title`, `data`, `created_at`, `updated_at`, `deleted_at`) VALUES
                                                                                                                           (11, 'mandate', NULL, 'कार्यादेश दिईएको', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<h4 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय:- कार्यादेश दिईएको बारे ।</strong></span></h4>\r\n\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n...............................</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14px\">प्रस्तुत विषय सम्बन्धमा ............................. को सिफारिश अनुसार तपशिलको कार्य गर्न तपाईंलाई यो कार्यादेश दिईएको छ। समयमै कार्य सम्पन्न गरी फरफारक गराउनु हुन अनुरोध छ।</span></p>\r\n\r\n<p><u><strong>तपशिल:</strong></u></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">सि. नं.</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">आयोजना/कार्यक्रमको नाम</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">पाना नं.</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">वडा नं./न. पा./शाखा</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">क्षेत्र</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">सि. नं.</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">विनियोजित रकम रु.</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">सम्पन्न गर्ने मिति</span></td>\r\n			<td style=\"text-align:center\"><span style=\"font-size:14px\">कैफियत</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\">....................................<br />\r\nप्रमुख प्रशासकिय अधिकृत</p>\r\n\r\n<p>&nbsp;</p>', '2023-01-23 09:58:05', '2023-01-29 05:05:15', NULL),
                                                                                                                           (12, 'project_agreement_form', 'consumer_committee', 'योजना सम्झौता फारम', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><span style=\"font-size:26px\"><strong>नेपालगन्ज उप-महानगरपालिका<br />\r\nनगर कार्यपालिका कार्यलय</strong><br />\r\nनेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:22px\"><u><strong>योजना सम्झौता फारम</strong></u></span></p>\r\n\r\n<p><span style=\"font-size:18px\">१. सम्झौता गर्ने पक्ष र आयोजना</span></p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;<strong>&nbsp; क) उपभोक्त्ता समितिको विवरण :</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; नाम :- </span>[@consumerCommittee.name]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ठेगाना :- </span>[@consumerCommittee.address]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; अध्यक्षको नाम :- </span>[@consumerCommittee.chairman]</p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;<strong> ख) आयोजनाको विवरण :</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; नाम :- </span>[@project_name]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; योजनाको स्तर :- </span>[@plan_level]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; योजना उपस्तर :- </span>[@plan_level]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;योजनाको क्षेत्र :- </span>[@plan_area]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;योजनाको उपक्षेत्र :- </span>[@plan_area]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;संचालन हुने वडा नं :- </span>[@ward_no]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेट शीर्षक :- </span>[@budget_head]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेट उप-शीर्षक :- </span>[@budget_head]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेटको श्रोत :- </span>[@budget_source]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;विनियोजित रकम रु :- </span>[@allocated_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना स्थल :- </span>[@project_venue]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;मूल्याङ्कन रकम रु :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;उद्देश्य :- </span>[@purpose]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना अवस्था :- </span>[@project_status]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना सुरु हुने मिति :- </span>[@project_start_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना सम्पन्&zwj;न हुने मिति :- </span>[@project_completion_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजनाको म्याद थप मिति :- </span>[@extended_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;वित्तीय प्रगति खर्च रकम रु :- </span>[@progress_spent_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति लक्ष्य :- </span>[@physical_progress_target]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति सम्पन्न :- </span>[@physical_progress_completed]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति एकाइ :- </span>[@physical_progress_unit]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>२. आयोजनाको लागत सम्वन्धि विवरण</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp; क) लागत अनुमान रु :- </strong></span>[@total_cost_estimate_amount]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp; ख) लागत व्यहोर्ने स्रोतहरु</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"height:77px; width:900px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>विवरण</strong></td>\r\n			<td><strong>रकम</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td>कार्यालयबाट स्वीकृत रकम</td>\r\n			<td>रू [@allocated_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य निकायबाट प्राप्त रकम</td>\r\n			<td>रू [@agencies_grants]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य साझेदारी रकम</td>\r\n			<td>रू [@share_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>समितिबाट नगद साझेदारी रकम</td>\r\n			<td>रू [@committee_share_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>कन्टिजेन्सी सहितको कुल रकम</td>\r\n			<td>रू [@total_amount_for_contingency]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>कन्टिजेन्सी कट्टी रकम</td>\r\n			<td>रू [@contingency_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य करकट्टी रकम</td>\r\n			<td>रू [@other_taxes]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>योजना सम्झौता रकम</td>\r\n			<td>रू [@project_contract_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>समितिबाट जनश्रमदान रकम</td>\r\n			<td>रू [@labor_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>कुल लागत अनुमान रकम</strong></td>\r\n			<td><strong>रू [@total_cost_estimate_amount]</strong></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp; <strong>&nbsp; ग) बस्तुगत अनुदानको विवरण</strong><strong>&nbsp;&nbsp;&nbsp; </strong></span></p>\r\n\r\n<p>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp; [@projectGrantDetails]</p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;<strong>&nbsp;&nbsp; घ) आयोजनाबाट लाभान्वित हुने</strong><br />\r\n&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp; १.घरपरिवार संख्या :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २.जनसंख्या :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ३.संगठित संस्था :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ४.अन्य :-</span></p>\r\n\r\n<p><span style=\"font-size:18px\">योजनाबाट प्रत्यक्ष रुपमा लाभान्वित हुने घरधुरी तथा जनसंख्याको विवरण</span></p>\r\n\r\n<p>[@benefitedMemberDetails]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>३. उपभोक्ता समिति/समुदायमा आधारित संस्था/गैरसरकारी संस्थाको विवरण</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; क) गठन भएको मिति :- </strong></span>[@consumerCommittee.formation_date]<br />\r\n<span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; ख) पदाधिकारीको नाम र ठेगाना (नागरिकता प्रमाणपत्र नम्बर र जिल्ला</strong></span></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; [@consumerCommittee.consumerCommitteeOfficials]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp; &nbsp; ग) गठन गर्दा उपस्थित लाभान्वितको संख्या :- </strong></span>[@consumerCommittee.beneficiary_no]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>४. आयोजना संचालन सम्बन्धी अनुभव :- </strong></span>[@consumerCommittee.experience_in_project]</p>\r\n\r\n<p><strong><span style=\"font-size:18px\">५. उपभोक्ता समिति समुदायमा अधारित संस्था गैरसरकारी संस्थाले प्राप्त गर्ने किस्ता विवरण:</span></strong></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">किस्ताको क्रम</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">मिति</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">किस्ताको रकम</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">निर्माण समाग्री परिमाण</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">कैफियत</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">कागजातहरु</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">सम्पादन</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:18px\"><strong>६. पेश्की विवरण</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">क्र.सं.</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">पेश्की रकम</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">पेस्की दिएको मिति</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:18px\"><strong>७. आयोजना मर्मत संम्भार सम्बन्धी व्यवस्था<br />\r\nक) आयोजना मर्मत संम्भारको जिम्मा लिने समिति संस्थाको नाम : </strong></span>[@projectMaintenanceArrangement.office_name]<br />\r\n<span style=\"font-size:18px\"><strong>ख) मर्मत संम्भारको सम्भावित स्रोत (छ छैन खुलाउने)</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:18px\">जनश्रमदान : </span>[@projectMaintenanceArrangement.public_service]</li>\r\n	<li><span style=\"font-size:18px\">सेवा शुल्क : </span>[@projectMaintenanceArrangement.service_fee]</li>\r\n	<li><span style=\"font-size:18px\">दस्तुर, चन्दाबाट : </span>[@projectMaintenanceArrangement.from_fee_donation]</li>\r\n	<li><span style=\"font-size:18px\">अन्य केही भए : </span>[@projectMaintenanceArrangement.others]</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:18px\"><strong>८. सम्झौताको सर्तहरू</strong></span></p>\r\n\r\n<p>&nbsp; [@projectAgreementTerm.data]</p>', '2023-01-24 06:30:54', '2023-01-29 07:09:08', NULL),
                                                                                                                           (13, 'project_agreement_form', 'bid', 'आयोजनाको विवरण', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/np.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><span style=\"font-size:26px\"><strong>नेपालगन्ज उप-महानगरपालिका<br />\r\nनगर कार्यपालिका कार्यलय</strong><br />\r\nनेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:22px\"><u><strong>योजना सम्झौता फारम</strong></u></span></p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;<strong> १) आयोजनाको विवरण :</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; नाम :- </span>[@project_name]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; योजनाको स्तर :- </span>[@plan_level]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; योजना उपस्तर :- </span>[@plan_level]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;योजनाको क्षेत्र :- </span>[@plan_area]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;योजनाको उपक्षेत्र :- </span>[@plan_area]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;संचालन हुने वडा नं :- </span>[@ward_no]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेट शीर्षक :- </span>[@budget_head]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेट उप-शीर्षक :- </span>[@budget_head]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;बजेटको श्रोत :- </span>[@budget_source]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;विनियोजित रकम रु :- </span>[@allocated_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना स्थल :- </span>[@project_venue]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;मूल्याङ्कन रकम रु :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;उद्देश्य :- </span>[@purpose]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना अवस्था :- </span>[@project_status]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना सुरु हुने मिति :- </span>[@project_start_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजना सम्पन्&zwj;न हुने मिति :- </span>[@project_completion_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;आयोजनाको म्याद थप मिति :- </span>[@extended_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;वित्तीय प्रगति खर्च रकम रु :- </span>[@progress_spent_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति लक्ष्य :- </span>[@physical_progress_target]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति सम्पन्न :- </span>[@physical_progress_completed]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;भौतिक प्रगति एकाइ :- </span>[@physical_progress_unit]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>२. आयोजनाको लागत सम्वन्धि विवरण</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp; क) लागत अनुमान रु :- </strong></span>[@total_cost_estimate_amount]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp; ख) लागत अनुमान (भ्याट, ओभर हेड, कन्टिन्जेन्सी बाहेक): -</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ग) लागत व्यहोर्ने स्रोतहरु</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"height:77px; width:900px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>विवरण</strong></td>\r\n			<td><strong>रकम</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td>कार्यालयबाट स्वीकृत रकम</td>\r\n			<td>रू [@allocated_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य निकायबाट प्राप्त रकम</td>\r\n			<td>रू [@agencies_grants]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य साझेदारी रकम</td>\r\n			<td>रू [@share_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>समितिबाट नगद साझेदारी रकम</td>\r\n			<td>रू [@committee_share_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>कन्टिजेन्सी सहितको कुल रकम</td>\r\n			<td>रू [@total_amount_for_contingency]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>कन्टिजेन्सी कट्टी रकम</td>\r\n			<td>रू [@contingency_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>अन्य करकट्टी रकम</td>\r\n			<td>रू [@other_taxes]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>योजना सम्झौता रकम</td>\r\n			<td>रू [@project_contract_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>समितिबाट जनश्रमदान रकम</td>\r\n			<td>रू [@labor_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>कुल लागत अनुमान रकम</strong></td>\r\n			<td><strong>रू [@total_cost_estimate_amount]</strong></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div style=\"page-break-after:always\"><span style=\"display:none\">&nbsp;</span></div>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp; <strong>&nbsp; घ) बस्तुगत अनुदानको विवरण</strong><strong>&nbsp;&nbsp;&nbsp; </strong></span></p>\r\n\r\n<p>&nbsp;&nbsp; [@projectGrantDetails]</p>\r\n\r\n<p><span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;<strong>&nbsp;&nbsp; ङ) आयोजनाबाट लाभान्वित हुने</strong><br />\r\n&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp; १.घरपरिवार संख्या :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २.जनसंख्या :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ३.संगठित संस्था :-<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ४.अन्य :-</span></p>\r\n\r\n<p><span style=\"font-size:18px\">योजनाबाट प्रत्यक्ष रुपमा लाभान्वित हुने घरधुरी तथा जनसंख्याको विवरण</span></p>\r\n\r\n<p>[@benefitedMemberDetails]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>३. बोलपत्र सम्वन्धि विवरण</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; क) कार्यालयको स्वीकृत विभागिय लागत अनुमान :- </strong></span>[@projectBidDetail.cost_estimation]<br />\r\n<span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; ख) १.बोलपत्र नं :-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २.बोलपत्रको सुचना प्रकाशित मिति :- </strong></span>[@projectBidDetail.notice_published_date]<span style=\"font-size:18px\"><strong>&nbsp;&nbsp; ३.पत्रिकाको नाम :- </strong></span>[@projectBidDetail.newspaper_name]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp; &nbsp; ग) ठेक्का विवरण</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; ठेक्का मुल्यांकनको निर्णय मिति :- </span>[@projectBidDetail.contract_evaluation_decision_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; आशयको सुचना प्रकाशित मिति :- </span>[@projectBidDetail.intent_notice_publish_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; पत्रिकाको नाम :- </span>[@projectBidDetail.contract_newspaper_name]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ठेक्का स्वीकृतीको निर्णय मिति :- </span>[@projectBidDetail.contract_acceptance_decision_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ठेक्का विलो प्रतिशत :- </span>[@projectBidDetail.contract_percentage]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; घ) १.ठेकेदारको नाम :-&nbsp;</strong></span>[@projectBidDetail.contractor_name]<span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २.ठेकेदारको ठेगाना :- </strong></span>[@projectBidDetail.contractor_address]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; ङ) सम्पर्क नम्बर :- </strong></span>[@projectBidDetail.contractor_phone]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; च) कबोल अंक :- </strong></span>[@projectBidDetail.confession_number]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; छ) विडवण्ड विवरण</strong></span><br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; १.विडवण्ड नं :- </span>[@projectBidDetail.bid_bond_no]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; २.विडवण्ड रकम :- </span>[@projectBidDetail.bid_bond_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; ३.बैंकको नाम :- </span>[@projectBidDetail.bid_bond_bank_name]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; ४.जारी मिति :- </span>[@projectBidDetail.bid_bond_issue_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ५.म्याद सकिने मिति :- </span>[@projectBidDetail.bid_bond_expiry_date]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; ज) परफरमेन्स वण्ड विवरण</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; १.परफरमेन्स वण्ड नं :- </span>[@projectBidDetail.performance_bond_no]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; २.परफरमेन्स वण्ड रकम :- </span>[@projectBidDetail.performance_bond_amount]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ३.बैंकको नाम :- </span>[@projectBidDetail.performance_bond_bank]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; ४.जारी मिति :- </span>[@projectBidDetail.performance_bond_issue_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ५.म्याद सकिने मिति :- </span>[@projectBidDetail.performance_bond_expiry_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ६.म्याद थपको मिति :- </span>[@projectBidDetail.performance_bond_extended_date]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; झ) १.ठेक्का सम्झौता मिति :-&nbsp;</strong></span>[@projectBidDetail.contract_agreement_date]<span style=\"font-size:18px\"><strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; २.कार्यादेशको मिति :- </strong></span>[@projectBidDetail.contract_assigned_date]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>&nbsp;&nbsp;&nbsp; ञ) इन्स्योरेन्स विवरण</strong><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; १. जारी मिति :- </span>[@projectBidDetail.insurance_issue_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; २. सकिने मिति :- </span>[@projectBidDetail.insurance_expiry_date]<br />\r\n<span style=\"font-size:18px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; ३. म्याद थप हुने मिति :- </span>[@projectBidDetail.insurance_extended_date]</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>४. मोविलाईजेशन पेश्की/रनिङ विल विवरण</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">बिल/पेश्कीको प्रकार</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">बिल/पेश्कीको क्रम</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">मिति</span></td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:#ffffff; color:rgba(0, 0, 0, 0.87); font-family:Roboto,Helvetica,Arial,sans-serif; font-size:14px\">रकम</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:18px\"><strong>५. सम्झौताको सर्तहरू</strong></span></p>\r\n\r\n<p>&nbsp; [@projectAgreementTerm.data]</p>', '2023-01-24 08:42:31', '2023-01-27 10:47:31', NULL),
                                                                                                                           (14, NULL, NULL, 'प्रथम किस्ता रकम निकासा दिने सम्बन्धमा', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:6rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong><u>टिप्पणी&nbsp;र आदेश</u></strong></span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:16px\">विषय:- <u>प्रथम किस्ता रकम निकासा दिने सम्बन्धमा </u>।</span><span style=\"font-size:22px\"> </span></h4>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; नगरसभाबाट&nbsp;स्वीकृत&nbsp;निम्न&nbsp;अनुसारको&nbsp;योजनाको&nbsp;उपभोक्ता समिति गठन भई&nbsp;उपभोक्ता&nbsp;समिति&nbsp;र&nbsp;यसकार्यालयबीच&nbsp;सम्झौता&nbsp;समेत सम्पन्न&nbsp;भईसकेको हुँदा&nbsp;उपभोक्ता समितिको&nbsp;बैंक खाता मार्फत पेश्की रकम उपलव्ध गराउन यस कार्यालयमा निवेदन पेश भएको ।</p>\r\n\r\n<p>आयोजना सम्वन्धी विवरण :-<br />\r\nयोजनाको नाम :-<br />\r\nठेगाना :-<br />\r\nयोजनाको किसिम :-<br />\r\nयोजना सन्चालन भएको स्थान :-<br />\r\nकुल&nbsp;लागत अनुमान रकम&nbsp;रू :-<br />\r\nअनुदान रकम&nbsp;रू :-<br />\r\nकन्टेन्जेन्सी रकम रू :-<br />\r\nजनसहभागिताको रकम&nbsp;रू :-<br />\r\nआयोजना शुरु भएको मिति :-<br />\r\nआयोजना सम्पन्न हुने मिति :-</p>\r\n\r\n<p>उल्लिखित योजनाको लागि उपभोक्ता समितिका अध्यक्ष ....................... को नाममा&nbsp;उपभोक्ता समितिको बैंक खातामार्फत रु मात्र प्रथम किस्ता पेश्की रकम उपलव्ध गराउन मनासिब देखि निर्णयार्थ पेश गरेको छु ।</p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nपेश गर्ने </span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">...................................<br />\r\nरुजु गर्ने</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">...................................<br />\r\nस्वीकृत गर्ने</span></div>\r\n</div>', '2023-01-25 04:55:44', '2023-01-25 04:55:44', NULL),
                                                                                                                           (15, NULL, NULL, 'योजना सम्झौता सम्बन्ध', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p style=\"text-align:center\"><strong><span style=\"font-size:16px\">विषय : योजना सम्झौता सम्बन्धमा ।</span></strong></p>\r\n\r\n<p>श्रीमान,<br />\r\nप्रमुख प्रशासकिय अधिकृत ज्यू,&nbsp;&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; प्रस्तुत सन्दर्भमा यस दुहवीको आ.व.&nbsp;&hellip;&hellip;&hellip;&hellip;.&nbsp;को वार्षिक स्वीकृत बजेट तथा कार्यक्रमानुसार वडा नं. ..........&nbsp;&nbsp;मा कार्यान्वयन गर्ने गरी ................ योजना अन्तरगत रु. ..................... विनियोजन भएको र सोही योजना कार्यान्वयनको लागि कागजात प्राप्त भएको व्यहोरा जानकारीको लागि अनुरोध छ । यस गाँउपालिकाको वडा नं. .....&nbsp;&nbsp;मा गाँउपालिकाको आ.व. ............&nbsp;&nbsp;को स्वकृत योजना तथा कार्यक्रमको ................................. योजना भन्ने शिर्षकमा विनियोजन भएको रकमवाट कार्यान्वयन हुने गरि योजना सम्झौता गरी पाउं भनि सम्बन्धित वडा अध्यक्षको मिति ................&nbsp;&nbsp;गतेको सिफारिस सहित ......................&nbsp;&nbsp;गते उपभोक्ता समितिका अध्यक्ष .......................ले यस कार्यालयमा निवेदन साथै उपभोक्ता समिति गठनको माइनुटको फोटोकपी,&nbsp;समितिका सवै पदाधिकारीहरुको नागरिकताको फोटोकपी,&nbsp;प्राविधिक लागत अनुमान,&nbsp;सहित पेश गर्नु भएको हुँदा उक्त योजना सम्झौता गर्न प्राविधिकको लागत अनुमान बमोजिम मनासीव देखी निर्णयार्थ यो टिप्पणी पेश गरेको छु ।</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p>योजनाको नाम :-&nbsp;<br />\r\nस्वीकृत रकम :-<br />\r\nकन्टेन्जेन्सी कट्टी :-<br />\r\nसमितिले भुक्तानी पाउने रु :-<br />\r\nउपभोक्ता समितिको श्रमदान :-<br />\r\nश्रोत :-<br />\r\nसमिति अध्यक्षको नाम र ना.प्र.प.नं :-<br />\r\nसम्पर्क नं.&nbsp;:-</p>', '2023-01-25 05:03:31', '2023-01-25 05:03:31', NULL),
                                                                                                                           (16, NULL, NULL, 'भुक्तानी टिप्पणी', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:6rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति: ..................................</span></p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>टिप्पणी र आदेश</strong></span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:16px\">विषय:- म्याद थप गरिएको बारे।</span></h4>\r\n\r\n<p style=\"text-align:center\">(<u>@budgetTitle</u>)</p>\r\n\r\n<p><span style=\"font-size:14px\">श्रीमान,</span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; यस सुर्यगढी गाउँपालिका वडा नं. ............. स्थित ............... योजना निर्माणको लागि मिति ............... तथा मिति ............. मा सम्पन्न नवौं र दशौं गाउँसभाबाट स्वीकृत निम्न लेखिय बमोजिमको गाउँपालिका स्तरीय योजना कार्यान्वयनको लागि सार्वजनिक खरिद ऐन-२०६३ (पहिलो संशोधन) को दफा ११, सार्वजनिक खरिद नियमावली २०६४ (दशौँ संशोधन) को नियम ९७, <u>सुर्यगढी गाउँपालिका</u>को सार्वजनिक खरिद नियमावली २०७७ को नियम १०७ को उपनियम १ तथा <u>सुर्यगढी गाउपालिका</u>को उपभोक्ता समिति गठन, परिचालन तथा व्यवस्थापन सम्बन्धी कार्यविधि २०७६ को दफा ४ मा व्यवस्था गरिय बमोजिम उपभोक्ता समिति गठन गरी सुर्यगढी गाउँपालिकाको कार्यालय र उपभोक्ता समिति बिच मिति<u> @aayojanaSuruHuneMiti</u> मा सम्झौता भएको र उक्त कार्यविधिको दफा ११ बमोजिम प्राविधिक लागत ईस्टिमेट अनुसार निर्माण कार्य सुरु गरी मिति <u>@aayojanaSampannaHuneMiti</u> मा निर्माण कार्य सम्पन्न भएको भनि सम्बन्धित उपभोक्ता समितिको निवेदन, वडा कार्यालयको सिफारिस, वडा स्तरीय अनुगमन समितिको प्रतिवेदन, प्राविधिक कार्य सम्पन्न प्रतिवेदन, बिल, डोर हाजिरी, सार्वजनिक परिक्षण, फोटो र उपभोक्ता समितिको निर्णय पेश भएकोले तपशिल बमोजिमको रकम अनुतिम किस्ता भुक्तानी दिन मनासिब देखि निर्णयार्थ पेश गरेको छु ।</p>\r\n\r\n<p>योजनाको विवरण :</p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>योजनाको नामः</td>\r\n			<td>@aayojanaName</td>\r\n		</tr>\r\n		<tr>\r\n			<td>स्थानः</td>\r\n			<td>@aayojanaAddress</td>\r\n		</tr>\r\n		<tr>\r\n			<td>काम सुरु भएको मितिः</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>काम सम्पन्न भएको मितिः</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>योजनाको कुल लागत अनुमानः</td>\r\n			<td>@estimatedTotalCostInNumber</td>\r\n		</tr>\r\n		<tr>\r\n			<td><u>सुर्यगढी गा.पा</u> को अनुदानः</td>\r\n			<td>@allocatedAmount</td>\r\n		</tr>\r\n		<tr>\r\n			<td>उपभोक्ताहरुको जनसहभागिताः</td>\r\n			<td>@fundFromPublicLabourDonationInNumber</td>\r\n		</tr>\r\n		<tr>\r\n			<td>कन्टिन्जेन्सी कट्टी रकम (४%)</td>\r\n			<td>@contingencyAmountFromPercent</td>\r\n		</tr>\r\n		<tr>\r\n			<td>लागत स्टिमेट बमोजिम भुक्तानी हुने जम्मा रकमः</td>\r\n			<td>@allocatedAmount-@contingencyAmountFromPercent</td>\r\n		</tr>\r\n		<tr>\r\n			<td>पेश्की रकमः</td>\r\n			<td>@peskeAmountInNumber</td>\r\n		</tr>\r\n		<tr>\r\n			<td>भुक्तानी हुन बाँकी रकमः</td>\r\n			<td>@allocatedAmount-@contingencyAmountFromPercent-@peskeAmountInNumber</td>\r\n		</tr>\r\n		<tr>\r\n			<td>प्राविधिक मुल्याङ्कन र कार्य सम्पन्न प्रतिबेदन अनुसारको रकमः</td>\r\n			<td>\r\n			<p>@evaluationAmountInNumber (जनसहभागिता सहित)</p>\r\n\r\n			<p>@evaluationAmountInNumber/@estimatedTotalCostInNumber*100 % कार्य</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>प्राविधिक मुल्याङ्कन र कार्य सम्पन्न प्रतिबेदन अनुसार उपभोक्ता समिति मार्फत अन्तिम किस्ता भुक्तानी हुने कुल रकमः</td>\r\n			<td>@allocatedAmount-@contingencyAmountFromPercent-@peskeAmountInNumber*@evaluationAmountInNumber/@estimatedTotalCostInNumber*100 %</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"flex-container mt-5\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nतयार गर्ने&nbsp;<br />\r\nयोजना शाखा </span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nचेकजाँच गर्ने<br />\r\nप्राविधिक शाखा </span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nसिफारिस गर्ने<br />\r\nआर्थिक प्रशासन </span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:4rem; margin-right:4rem; margin-top:4rem; text-align:center\"><span style=\"font-size:14px\">....................................<br />\r\nप्रमाणीत गर्ने<br />\r\nप्र.प्रशासकीय अधिकृत</span><span style=\"font-size:18px\"><strong> </strong></span></div>\r\n</div>\r\n\r\n<p>&nbsp;</p>', '2023-01-25 05:35:55', '2023-01-25 05:38:08', NULL),
                                                                                                                           (17, 'regarding_planning_agreement_providing_submissions', 'consumer_committee', 'योजना सम्झौता गरी पेश्की उपलब्ध गराउने सम्बन्धमा', '<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:4rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/logo.png\" style=\"float:left; height:90px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:1rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">नेपालगन्ज उप-महानगरपालिका</span><br />\r\n<span style=\"font-size:16px\">नगर कार्यपालिका कार्यलय</span></strong><br />\r\n<span style=\"font-size:14px\">नेपालगन्ज,बाँके<br />\r\nलुम्बिनी प्रदेश,नेपाल</span></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\"><span style=\"font-size:16px\">पत्र स.नं. ................................<br />\r\nचलानी नं ...........................</span></div>\r\n\r\n<div class=\"col-md-6 text-end\">\r\n<p style=\"text-align:right\"><span style=\"font-size:16px\">मिति :</span> [@date]</p>\r\n</div>\r\n</div>\r\n\r\n<hr />\r\n<p><span style=\"font-size:14px\">श्री ..............................<br />\r\n...............................</span></p>\r\n\r\n<h2 style=\"text-align:center\"><strong>टिप्पणी र आदेश</strong></h2>\r\n\r\n<h4 style=\"text-align:center\"><strong>बिषय : योजना सम्झौता गरी पेश्की उपलब्ध गराउने सम्बन्धमा</strong></h4>\r\n\r\n<p>श्रीमान,</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; यस कार्यालयको स्वीकृत बार्षिक कार्यक्रम अनुसार तपसिलका विवरण अनुसारका कागजात एवम प्रकृया पुरा भएको देखिएकोले उ.स / ग.स.स को .... मा रहेको खाता नं मा रु......पेश्की निकाशा दिन निर्णयाथ पेश गरेको छु | जो आदेश</span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><strong>तपशिल:</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"height:434px; width:1035px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>सि.नं.</strong></td>\r\n			<td><strong>बिषय/विवरण</strong></td>\r\n			<td><strong>रकम</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td>१</td>\r\n			<td>आर्थिक बर्ष : [@fiscalYear]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>२</td>\r\n			<td>अयोजनाको नाम : [@project_name]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>३</td>\r\n			<td>ठेगाना : [@project_venue]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>४</td>\r\n			<td>योजना स्वीकृत मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>५</td>\r\n			<td>बजेट शिर्षक नं : [@registration_no]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>६</td>\r\n			<td>कार्यक्रमको नाम :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>७</td>\r\n			<td>उपभोग्ता समितिको नाम : [@consumerCommittee.name]</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>८</td>\r\n			<td>उपभोग्ता समितिको बैंक खाता नं:</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>९</td>\r\n			<td>उपभोग्ता समितिसंग सम्झौता मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१०</td>\r\n			<td>उपभोग्ता समितिको निर्णय मिति :</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>११</td>\r\n			<td>स्वीकृत रकम :</td>\r\n			<td>रु . [@allocated_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१२</td>\r\n			<td>लागत अनुमान:</td>\r\n			<td>रु . [@total_cost_estimate_amount]</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td><strong>लागत व्यहोर्ने श्रोतहरु : </strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>१३